package com.guocheng.mediapocket;
import android.app.Activity;import android.content.SharedPreferences;import android.os.*;import org.json.*;import java.util.*;import java.util.regex.*;
/** 显式轨道只作用于带有该 id 的片源；开播时也按偏好自动选择中文（简体优先）或英文字幕。 */
final class TrackSelection {
 static final int DISABLE=-1,UNCHANGED=-2;
 static final Pattern LANGS=Pattern.compile("简体中文|繁体中文|繁體中文|Chinese Simplified|Chinese Traditional|简体|繁体|繁體|简中|繁中|中文字幕|中文|中字|English|英文|英语|\\bCHS\\b|\\bCHT\\b|\\bENG\\b",Pattern.CASE_INSENSITIVE);
 static JSONObject stream(Activity a){Object value=OnlineSubtitleSearch.field(a,"stream");if(value instanceof JSONObject)return (JSONObject)value;try{return new JSONObject(a.getIntent().getStringExtra("stream"));}catch(Exception e){return new JSONObject();}}
 static boolean hasAudio(JSONObject s){return s.has("mp.audioTrack");}
 static boolean hasSubtitle(JSONObject s){return s.has("mp.subtitleTrack");}
 static boolean contains(Object tracks,int target){if(target==-1)return true;if(tracks instanceof Object[])for(Object track:(Object[])tracks){if(track==null)continue;Object id=trackId(track);if(id instanceof Number&&((Number)id).intValue()==target)return true;}return false;}
 static Object trackId(Object track){for(Class<?> c=track.getClass();c!=null;c=c.getSuperclass())try{java.lang.reflect.Field field=c.getDeclaredField("id");field.setAccessible(true);return field.get(track);}catch(Exception ignored){}return null;}
 static boolean sameSource(JSONObject one,JSONObject two){return one==two||one.optString("url").equals(two.optString("url"))&&one.optString("infoHash").equals(two.optString("infoHash"))&&one.optInt("fileIdx",-1)==two.optInt("fileIdx",-1);}
 /** 字幕文字归类：hans 简体、hant 繁体、zh 未标明字形的中文、en、off（无字幕/关闭）、other。 */
 static String script(String raw){String n=raw==null?"":raw.toLowerCase(Locale.ROOT);if(n.isEmpty())return "other";if(isOff(n))return "off";if(n.contains("简体")||n.contains("简中")||n.contains("simplified")||n.contains("zh-hans")||n.contains("zh-cn")||n.contains("chs"))return "hans";if(n.contains("繁体")||n.contains("繁體")||n.contains("繁中")||n.contains("traditional")||n.contains("zh-hant")||n.contains("zh-tw")||n.contains("zh-hk")||n.contains("cht")||n.contains("big5"))return "hant";if(n.contains("中文")||n.contains("中字")||n.contains("chinese")||n.contains("国语")||n.contains("普通话")||PlaybackPrefs.has(n,"chi")||PlaybackPrefs.has(n,"zho")||PlaybackPrefs.has(n,"zh"))return "zh";if(n.contains("英文")||n.contains("英语")||n.contains("english")||PlaybackPrefs.has(n,"eng")||PlaybackPrefs.has(n,"en"))return "en";return "other";}
 static boolean isOff(String n){return n.contains("无字幕")||n.contains("禁用")||n.contains("关闭")||n.contains("disable")||n.contains("no subtitle")||n.equals("none")||n.equals("off");}
 static boolean commentary(String n){String l=n==null?"":n.toLowerCase(Locale.ROOT);return l.contains("commentary")||l.contains("评论");}
 static boolean sparse(String n){String l=n==null?"":n.toLowerCase(Locale.ROOT);return l.contains("forced")||l.contains("signs")||l.contains("songs")||l.contains("lyrics")||l.contains("歌词")||l.contains("特效");}
 /** 越高越适合。评论轨和不属于中/英的轨为 -1。简体高于未标明字形的中文，再高于繁体。 */
 static int score(String label,String pref){if(commentary(label))return -1;String k=script(label);if(k.equals("off")||k.equals("other"))return -1;int base;if("eng".equals(pref))base=k.equals("en")?300:k.equals("hans")?120:k.equals("zh")?100:k.equals("hant")?80:-1;else base=k.equals("hans")?300:k.equals("zh")?220:k.equals("hant")?160:k.equals("en")?40:-1;if(base<0)return -1;return sparse(label)?base-50:base;}
 /** 排序用，数值越小越优先。all 保持原顺序。 */
 static int rank(String language,String preferred){if(preferred==null||preferred.equals("all"))return 0;String k=script(language);if(commentary(language))return 8;if("eng".equals(preferred))return k.equals("en")?0:k.equals("hans")?1:k.equals("zh")?2:k.equals("hant")?3:9;if("hant".equals(preferred))return k.equals("hant")?0:k.equals("zh")?1:k.equals("hans")?2:k.equals("en")?3:9;return k.equals("hans")?0:k.equals("zh")?1:k.equals("hant")?2:k.equals("en")?3:9;}
 /** 音轨已是偏好语言时不必再挂同语言字幕；外语或未知则需要。 */
 static boolean needed(String pref,String audioLang){if(pref==null||pref.equals("off"))return false;if(pref.equals("zho")&&(audioLang.equals("zh")||audioLang.equals("yue")))return false;if(pref.equals("eng")&&audioLang.equals("en"))return false;return true;}
 /** 偏好音轨，否则从片名里认国语/粤语/英语。字幕行里的「简体/中字」不算音轨。 */
 static String audioLanguage(String text,String audioPref){if("zh".equals(audioPref)||"yue".equals(audioPref)||"en".equals(audioPref))return audioPref;String n=" "+(text==null?"":text.toLowerCase(Locale.ROOT))+" ";boolean zh=n.contains("国语")||n.contains("普通话")||n.contains("中配")||n.contains("mandarin");boolean yue=n.contains("粤语")||n.contains("cantonese");boolean en=n.contains("english")||n.contains(" eng ")||n.contains("英语");if((zh||yue)&&!en)return yue&&!zh?"yue":"zh";if(en)return "en";return "unknown";}
 static String observedAudio(String name){if(name==null||name.isEmpty())return "unknown";String n=name.toLowerCase(Locale.ROOT);if(n.contains("粤")||n.contains("cantonese")||PlaybackPrefs.has(n,"yue"))return "yue";String k=script(name);if(k.equals("hans")||k.equals("hant")||k.equals("zh"))return "zh";if(k.equals("en"))return "en";if(n.contains("japan")||n.contains("日本")||n.contains("korean")||n.contains("韩")||n.contains("french")||n.contains("法语")||PlaybackPrefs.has(n,"jpn")||PlaybackPrefs.has(n,"kor"))return "other";return "unknown";}
 /** 音轨列表已经出现时，以真实音轨为准；偏好语言在列表里就按偏好，否则看当前轨。 */
 static String resolveAudio(String hinted,String audioPref,String[] names,int[] ids,int current){if(names!=null&&audioPref!=null&&!audioPref.equals("auto")){for(String name:names)if(name!=null&&PlaybackPrefs.matches(name.toLowerCase(Locale.ROOT),audioPref))return audioPref.equals("en")?"en":audioPref.equals("yue")?"yue":"zh";}if(names!=null&&ids!=null)for(int i=0;i<Math.min(names.length,ids.length);i++)if(ids[i]==current){String o=observedAudio(names[i]);if(!o.equals("unknown"))return o;}return hinted==null?"unknown":hinted;}
 /** Stremio 标题/简介里按出现顺序抽出的字幕语言，同字形只留第一次。 */
 static String[] languages(String text){if(text==null||text.isEmpty())return new String[0];Matcher m=LANGS.matcher(text);ArrayList<String> out=new ArrayList<>(),seen=new ArrayList<>();while(m.find()){String token=m.group(),k=script(token);if(k.equals("other")||k.equals("off")||seen.contains(k))continue;seen.add(k);out.add(token);}return out.toArray(new String[0]);}
 /**
  * 返回应选下标。DISABLE 表示关掉字幕（偏好关闭，或音轨已是偏好语言）。
  * UNCHANGED 表示没有更合适的中/英轨，保留播放器现状。
  * titleLangs 与「Track 1」这类无名轨数量一致时，按标题顺序对上。
  */
 static String[] mapped(String[] labels,String[] titleLangs){String[] use=new String[labels.length];int unnamed=0;for(int i=0;i<labels.length;i++){use[i]=labels[i]==null?"":labels[i];if("other".equals(script(use[i]))&&!commentary(use[i]))unnamed++;}if(titleLangs!=null&&unnamed>0&&unnamed==titleLangs.length){int t=0;for(int i=0;i<use.length;i++)if("other".equals(script(labels[i]==null?"":labels[i]))&&!commentary(labels[i]))use[i]=titleLangs[t++];}return use;}
 static int pick(String[] labels,boolean[] embedded,String pref,String audioLang,String[] titleLangs){if(labels==null||"off".equals(pref))return DISABLE;String[] use=mapped(labels,titleLangs);if(!needed(pref,audioLang==null?"unknown":audioLang))return DISABLE;int best=-1,bestScore=0;for(int i=0;i<use.length;i++){int s=score(use[i],pref);if(s<0)continue;if(embedded!=null&&i<embedded.length&&embedded[i])s+=15;if(s>bestScore){bestScore=s;best=i;}}return best>=0?best:UNCHANGED;}
 static final class Sub {final String label;final int id;final JSONObject external;Sub(String label,int id,JSONObject external){this.label=label;this.id=id;this.external=external;}boolean embedded(){return external==null;}}
 /** 片源里已经写明的字幕：SourceTracks 内嵌轨，以及 StreamSubtitles 外挂地址。 */
 static ArrayList<Sub> listed(JSONObject stream){ArrayList<Sub> out=new ArrayList<>();if(stream==null)return out;JSONObject tracks=stream.optJSONObject("mp.tracks");JSONArray emb=tracks==null?null:tracks.optJSONArray("subtitles");if(emb!=null)for(int i=0;i<emb.length();i++){JSONObject item=emb.optJSONObject(i);if(item!=null)out.add(new Sub(item.optString("label"),item.optInt("id",-1),null));}JSONArray ext=stream.optJSONArray("subtitles");if(ext!=null)for(int i=0;i<ext.length();i++){JSONObject item=ext.optJSONObject(i);if(item!=null&&!item.optString("url").isEmpty())out.add(new Sub((item.optString("lang")+" "+item.optString("name")).trim(),-1,item));}return out;}
 static int bestIndex(ArrayList<Sub> hits,String pref,String audioLang){String[] labels=new String[hits.size()];boolean[] emb=new boolean[hits.size()];for(int i=0;i<hits.size();i++){labels[i]=hits.get(i).label;emb[i]=hits.get(i).embedded();}return pick(labels,emb,pref,audioLang,null);}
 /** 元数据里最合适的内嵌轨 id；没有内嵌优胜者时返回 UNCHANGED 或 DISABLE。 */
 static int bestId(JSONObject stream,String pref,String audioLang){ArrayList<Sub> hits=listed(stream);int i=bestIndex(hits,pref,audioLang);if(i==DISABLE)return DISABLE;if(i<0||!hits.get(i).embedded())return UNCHANGED;return hits.get(i).id;}
 static String bestUrl(JSONObject stream,String pref,String audioLang){ArrayList<Sub> hits=listed(stream);int i=bestIndex(hits,pref,audioLang);if(i<0||hits.get(i).external==null)return "";return hits.get(i).external.optString("url");}
 static int externalScore(JSONObject stream,String pref){int top=-1;for(Sub h:listed(stream))if(h.external!=null){int s=score(h.label,pref);if(s>top)top=s;}return top;}
 static JSONArray externalQueue(JSONObject stream,String pref,String audioLang){JSONArray out=new JSONArray();if(!needed(pref,audioLang))return out;ArrayList<Sub> hits=listed(stream);int chosen=bestIndex(hits,pref,audioLang);if(chosen<0||hits.get(chosen).embedded())return out;ArrayList<Sub> ext=new ArrayList<>();for(Sub h:hits)if(h.external!=null&&score(h.label,pref)>=0)ext.add(h);String key=pref.equals("eng")?"eng":"zho";ext.sort((a,b)->Integer.compare(rank(a.label,key),rank(b.label,key)));for(Sub h:ext)out.put(h.external);return out;}
 static String[] trackNames(Object tracks,int[] ids){if(!(tracks instanceof Object[]))return null;Object[] list=(Object[])tracks;String[] names=new String[list.length];for(int i=0;i<list.length;i++){Object id=list[i]==null?null:OnlineSubtitleSearch.field(list[i],"id"),name=list[i]==null?null:OnlineSubtitleSearch.field(list[i],"name");ids[i]=id instanceof Integer?(Integer)id:-1;names[i]=name==null?"":name.toString();}return names;}
 static void spu(Object player,int id)throws Exception{OnlineSubtitleSearch.call(player,"setSpuTrack",new Class<?>[]{int.class},id);}
 static int currentSpu(Object player){try{Object v=OnlineSubtitleSearch.call(player,"getSpuTrack",new Class<?>[0]);if(v instanceof Integer)return (Integer)v;}catch(Exception ignored){}return Integer.MIN_VALUE;}
 static final java.util.Map<Activity,Handler> POLLS=java.util.Collections.synchronizedMap(new java.util.WeakHashMap<Activity,Handler>());
 static void dispose(Activity a){if(a==null)return;Handler h=POLLS.remove(a);if(h!=null)h.removeCallbacksAndMessages(null);}
 static JSONArray anyExternal(JSONObject stream,String pref){JSONArray out=new JSONArray();if(stream==null)return out;ArrayList<Sub> ext=new ArrayList<>();for(Sub h:listed(stream))if(h.external!=null)ext.add(h);String key="hant".equals(pref)?"hant":"eng".equals(pref)?"eng":"zho";ext.sort((a,b)->Integer.compare(rank(a.label,key),rank(b.label,key)));for(Sub h:ext)out.put(h.external);return out;}
 static void applyDelay(Object player,SharedPreferences prefs){if(player==null||prefs==null)return;try{OnlineSubtitleSearch.call(player,"setSpuDelay",new Class<?>[]{long.class},(long)SubtitlePrefs.clampOffset(prefs.getInt("sub.offsetMs",0))*1000L);}catch(Exception ignored){}}
 static void quietSpu(Activity a){try{Object video=OnlineSubtitleSearch.field(a,"video");Object player=video==null?null:OnlineSubtitleSearch.field(video,"player");if(player!=null)spu(player,-1);}catch(Exception ignored){}}
 static void startExternal(Activity a,JSONObject source,String pref,boolean[] started){if(started[0])return;JSONArray queue=anyExternal(source,pref);if(queue.length()==0)return;started[0]=true;SourceSubtitleLoader.load(a,queue,true);}
 static boolean cuesVisible(Activity a){Object cues=OnlineSubtitleSearch.field(a,"cues");return cues instanceof java.util.List&&!((java.util.List<?>)cues).isEmpty();}
 static boolean playing(Activity a,Object video){try{if(Boolean.TRUE.equals(OnlineSubtitleSearch.field(a,"rendered")))return true;if(video==null)return false;Object pos=OnlineSubtitleSearch.call(video,"getCurrentPosition",new Class<?>[0]);if(pos instanceof Integer&&(Integer)pos>0)return true;return Boolean.TRUE.equals(OnlineSubtitleSearch.call(video,"isPlaying",new Class<?>[0]));}catch(Exception e){return false;}}
 static void attach(Activity a){dispose(a);SubtitleMemory.release(a);JSONObject source=stream(a);SharedPreferences prefs=a.getSharedPreferences("data",0);String pref=PlaybackPrefs.subtitle(prefs),watch=SubtitleMemory.id(a);boolean explicitSub=hasSubtitle(source),explicitAudio=hasAudio(source),explicitOff=explicitSub&&source.optInt("mp.subtitleTrack",-1)<0,explicitPick=explicitSub&&!explicitOff;String[] titleLangs=languages(StreamInfo.text(source));final boolean[] externalStarted={false},restored={false},played={false},addonSearched={false};final Object[] initial={OnlineSubtitleSearch.field(a,"video")};Handler handler=new Handler(Looper.getMainLooper());POLLS.put(a,handler);handler.postDelayed(new Runnable(){int tries,playPolls;boolean audioDone=!explicitAudio,subtitleDone=false;public void run(){if(a.isFinishing()||a.isDestroyed()||++tries>240||!sameSource(stream(a),source))return;boolean userOff=explicitOff||(!watch.isEmpty()&&prefs.getBoolean("subtitleDisabled:"+watch,false));String saved=watch.isEmpty()?"":prefs.getString("subtitleUrl:"+watch,"");int remembered=explicitPick?source.optInt("mp.subtitleTrack",-1):(watch.isEmpty()?-1:prefs.getInt("subtitleSpu:"+watch,-1));String rememberedName=explicitPick?source.optString("mp.subtitleLabel",""):(watch.isEmpty()?"":prefs.getString("subtitleName:"+watch,""));Object video=OnlineSubtitleSearch.field(a,"video");/* 0.1.171：底座整页重开/换视图后 view 实例会变；原来直接 return 会把轮询静默掐死（不重排下一次），关闭/记忆再也无人接管。来源变化由 sameSource 兜底，视图换新就跟着新视图继续管。 */if(initial[0]!=null&&video!=null&&video!=initial[0])initial[0]=video;boolean on=playing(a,video);if(on)playPolls++;try{if(video!=null&&!audioDone){int target=source.optInt("mp.audioTrack",-1);Object tracks=OnlineSubtitleSearch.call(video,"audioTracks",new Class<?>[0]);if(contains(tracks,target)){OnlineSubtitleSearch.call(video,"audio",new Class<?>[]{int.class},target);audioDone=true;}}if(video!=null&&!subtitleDone){Object player=OnlineSubtitleSearch.field(video,"player");if(player!=null){Object raw=null;try{raw=OnlineSubtitleSearch.call(player,"getSpuTracks",new Class<?>[0]);}catch(Exception ignored){}int[] ids=raw instanceof Object[]?new int[((Object[])raw).length]:null;String[] names=ids==null?null:trackNames(raw,ids);JSONArray queue=anyExternal(source,pref);JSONObject best=queue.length()==0?null:queue.optJSONObject(0);SubtitleAuto.Poll poll=new SubtitleAuto.Poll();poll.tracks=ids==null?null:SubtitleAuto.fromNames(ids,names,titleLangs);poll.pref=pref;poll.userOff=userOff;poll.rememberedFile=!explicitPick&&saved!=null&&!saved.isEmpty();poll.rememberedId=remembered;poll.rememberedName=rememberedName==null?"":rememberedName;poll.hasSidecar=queue.length()>0;poll.sidecarPreferred=best!=null&&SubtitleAuto.preferredText((best.optString("lang")+" "+best.optString("name")).trim(),pref);poll.sidecarVisible=cuesVisible(a)&&!poll.rememberedFile;poll.playing=on;poll.waitedOut=playPolls>8;poll.manual=SubtitleMemory.held(a);SubtitleAuto.Step step=SubtitleAuto.vlcPoll(poll);if(step.loadSidecar)startExternal(a,source,pref,externalStarted);if(step.searchAddons&&!addonSearched[0]){addonSearched[0]=true;OnlineSubtitleSearch.autoAddons(a,pref);}if(step.cancelSidecar)SourceSubtitleLoader.stopAuto(a);/* 0.1.171：轨道列表没出来之前 current 读到的 -1 只是「尚未选择」，不是用户要的关闭态；既不能当成「已经关了」跳过下发，也不能就此收拍——否则冷启动时 VLC 稍后自己挂上默认轨，关闭记忆就失效了（重建路径因暖启动抢先下发而侥幸正确）。 */
/* 0.1.171：关闭态要穿过 VLC 的整个初始化窗口——列表出来了、current 还是 -1 可能只是「默认轨还没选」，不能据此跳过下发或收拍；关闭在 waitedOut（约 8 拍）内每拍重申，越过窗口（VLC 默认轨早已落定）才收拍。同轨重选的跳过只适用于具体轨道目标。 */if((step.spu==-1||step.spu>=0&&contains(raw,step.spu))&&!(step.spu>=0&&raw!=null&&SubtitleAuto.alreadySpu(currentSpu(player),step.spu)))spu(player,step.spu);if(!restored[0]){restored[0]=true;applyDelay(player,prefs);SecondarySubtitle.restore(a);}if(on&&!played[0]){played[0]=true;applyDelay(player,prefs);}if((userOff&&playPolls>8)||playPolls>24)subtitleDone=true;}}}catch(Exception ignored){}if(!audioDone||!subtitleDone)handler.postDelayed(this,playPolls>8?2000:800);}},500);}
}
